using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Diagnostics;using System.Text;using System.Threading;using System.Collections.Generic;using System.Windows.Forms;using System.Runtime.InteropServices;
namespace Frociart.Tests {
static class RuntimeCopyTests {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int count;
 [DllImport("user32.dll")]static extern uint GetClipboardSequenceNumber();
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static T Get<T>(object o,string name){return(T)o.GetType().GetField(name,F).GetValue(o);}
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
 static void Pump(int ms=30){var w=Stopwatch.StartNew();do{Application.DoEvents();Thread.Sleep(2);}while(w.ElapsedMilliseconds<ms);}
 static Diagram Diagram(params string[] texts){var d=new Diagram{Title="QA Copia risultato"};d.Nodes.Add(new FlowNode{Id="s",Kind=NodeKind.Start,Text="Inizio",Y=0});int i=0;foreach(string t in texts){d.Nodes.Add(new FlowNode{Id="o"+i,Kind=NodeKind.Output,Text="\""+t+"\"",Y=150+150*i});i++;}d.Nodes.Add(new FlowNode{Id="e",Kind=NodeKind.End,Text="Fine",Y=150+150*i});for(int n=1;n<d.Nodes.Count;n++)d.Edges.Add(new FlowEdge{From=d.Nodes[n-1].Id,To=d.Nodes[n].Id});return d;}
 static void Run(MainForm f,Diagram d){f.SetDocument(d,null,false);for(int i=0;i<30;i++){f.SingleStep();if(f.Runner!=null&&(f.Runner.State==RuntimeState.Completed||f.Runner.State==RuntimeState.Error))break;}Check(f.Runner!=null&&f.Runner.State==RuntimeState.Completed,"Actual interpreter completes test graph");Pump(270);}
 static void Capture(Control c,string name){Pump(230);var dir=Environment.GetEnvironmentVariable("REVIEW_OUTPUT");Directory.CreateDirectory(dir);using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save(Path.Combine(dir,name+".png"));}}
 sealed class ClipboardSnapshot:IDisposable {
  internal DataObject Data=new DataObject();internal bool Empty=true;internal readonly List<IDisposable> resources=new List<IDisposable>();internal uint OwnedSequence;internal bool Written;
  internal ClipboardSnapshot(){IDataObject old=Clipboard.GetDataObject();if(old==null)return;foreach(string format in old.GetFormats(false)){object value=old.GetData(format,false);if(value==null)continue;object frozen;
    if(value is string)frozen=value;else if(value is string[])frozen=((string[])value).Clone();else if(value is byte[])frozen=((byte[])value).Clone();else if(value is MemoryStream){var stream=new MemoryStream(((MemoryStream)value).ToArray());frozen=stream;resources.Add(stream);}else if(value is Image){var img=(Image)((Image)value).Clone();frozen=img;resources.Add(img);}else throw new Exception("Cannot safely preserve clipboard format; no clipboard write performed: "+format);
    Data.SetData(format,false,frozen);Empty=false;
  }}
  internal void Track(){OwnedSequence=GetClipboardSequenceNumber();Written=true;}
  public void Dispose(){if(Written){if(GetClipboardSequenceNumber()!=OwnedSequence)Console.WriteLine("CLIPBOARD: newer external content preserved");else{if(Empty)Clipboard.Clear();else Clipboard.SetDataObject(Data,true,5,40);Console.WriteLine("CLIPBOARD: original contents restored; no original contents logged");}}foreach(var r in resources)r.Dispose();}
 }
 [STAThread]static int Main(){try{
  Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);
  using(var clipboard=new ClipboardSnapshot())using(var form=new MainForm(null,true)){
   form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-2800,-2200);form.Size=new Size(1120,760);form.Show();Pump(320);form.EnterEditor();Pump(350);
   var card=Get<RuntimeSurface>(form,"runtimeOutputCard");var button=Get<FlowButton>(form,"copyOutputButton");var output=Get<TextBox>(form,"output");var empty=Get<Label>(form,"runtimeEmptyOutput");var tabs=Get<SidebarTabs>(form,"tabs");tabs.SelectedTab=Get<Panel>(form,"runTab");Pump(240);
   Check(!button.Visible&&!button.Enabled,"No inactive Copy action is presented before a result exists");Check(empty.Text.Contains("Premi Esegui"),"Empty result explains how to produce output");
   foreach(bool dark in new[]{true,false,true}){Ui.SetDarkMode(dark,false);Call(form,"RefreshRuntime");tabs.SelectedTab=Get<Panel>(form,"runTab");Get<Panel>(form,"runtimePanel").ScrollControlIntoView(card);Pump(220);Check(card.Visible&&empty.Visible&&Get<Label>(form,"outputLabel").Visible,"Empty state is visible in the real result pane "+dark+" (card="+card.Visible+", empty="+empty.Visible+", title="+Get<Label>(form,"outputLabel").Visible+", selected="+tabs.SelectedTab.Text+")");Check(card.BackColor==Ui.Raised&&output.BackColor==Ui.Raised,"Result and its read-only text share neutral themed surface "+dark);using(var b=new Bitmap(card.Width,card.Height)){card.DrawToBitmap(b,card.ClientRectangle);Check(b.GetPixel(card.Width/2,8).ToArgb()==Ui.Raised.ToArgb(),"Rendered result fill is neutral, without blue tint "+dark);}Capture(card,dark?"runtime-empty-dark":"runtime-empty-light");}
   Run(form,Diagram("Prima riga","","Caffè € 👩‍💻"));string expected="Prima riga"+Environment.NewLine+Environment.NewLine+"Caffè € 👩‍💻";Check(button.Visible&&button.Enabled,"Real output enables and reveals Copy");Check(button.AccessibleName=="Copia il risultato","Copy exposes its action to accessibility");Check(button.Bounds.Left>Get<Label>(form,"outputLabel").Right,"Result heading and Copy target never overlap");
   output.Select(0,3);button.PerformClick();clipboard.Track();Check(Clipboard.GetText(TextDataFormat.UnicodeText)==expected,"Real Windows clipboard receives complete Unicode output, including blank line and emoji");Check(button.Text=="Copiato"&&Get<Label>(form,"status").Text.Contains("copiato"),"Success is visible after the actual clipboard write");Check(output.SelectionStart==0&&output.SelectionLength==3,"Copy all preserves the user's partial text selection");Capture(card,"runtime-copied-dark");using(var b=new Bitmap(card.Width,card.Height)){card.DrawToBitmap(b,card.ClientRectangle);Check(b.GetPixel(button.Left,button.Top).ToArgb()==Ui.Raised.ToArgb(),"Copy corner matches its card: no dark rectangular cutout");}
   Pump(1900);Check(button.Text=="Copia"&&!Get<System.Windows.Forms.Timer>(form,"copiedOutputTimer").Enabled,"Copy confirmation expires and its timer stops");
   var native=form.RuntimeClipboardWrite;form.RuntimeClipboardWrite=text=>{throw new ExternalException("Simulated clipboard contention");};button.PerformClick();Check(button.Text=="Copia"&&Get<Label>(form,"status").Text.Contains("occupati"),"Busy clipboard never displays a false success and offers retry");Call(form,"RefreshRuntime");Check(Get<Label>(form,"outputLabel").Text=="COPIA NON RIUSCITA","Copy error remains visible across runtime refresh");Check(output.Text==expected&&Clipboard.GetText(TextDataFormat.UnicodeText)==expected,"Failure preserves result, clipboard and text");form.RuntimeClipboardWrite=native;button.PerformClick();clipboard.Track();Check(button.Text=="Copiato"&&Clipboard.GetText(TextDataFormat.UnicodeText)==expected,"Retry uses the real clipboard successfully");
   Call(form,"ResetRun",false);Check(!button.Visible&&!button.Enabled&&!Get<System.Windows.Forms.Timer>(form,"copiedOutputTimer").Enabled,"Reset hides Copy and cancels stale success state");
   Run(form,Diagram(""));Check(button.Visible&&empty.Text.Contains("riga vuota"),"An actual blank output is distinguished from no output");button.PerformClick();clipboard.Track();Check(Clipboard.ContainsText(TextDataFormat.UnicodeText)&&Clipboard.GetText(TextDataFormat.UnicodeText)==""&&button.Text=="Copiato","A real empty output line can be copied as empty Unicode text");
   Run(form,Diagram());Check(!button.Visible&&!button.Enabled&&empty.Text.Contains("Aggiungi un blocco Output"),"Completed program without Output explains the missing result");Capture(card,"runtime-no-output");
   Run(form,Diagram("Seconda esecuzione"));button.PerformClick();clipboard.Track();Check(Clipboard.GetText(TextDataFormat.UnicodeText)=="Seconda esecuzione","A later run copies its own output, never the previous result");Ui.SetDarkMode(false,false);Capture(card,"runtime-result-light");form.SetDocument(Diagram(),null,false);form.Close();Pump(270);Check(FlowTransitions.Active==0,"Closing releases confirmation transitions and timers");
  }
  Console.WriteLine("RUNTIME_COPY_PASS checks="+count+"; native Windows clipboard writes and restore; simulated busy-write failure; no original clipboard data logged");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
}
